preConditionHook:
// A COUNTERTREND TRADE IS A SCALP: the target is a FIXED PRICE LEVEL set on the
// fill bar, EntryPrice + scalpAtr x ATR (short: minus), and the trade comes off
// when a close reaches it. Replaces CountertrendScalpPercentTarget (removed
// 2026-09-17): a percentage of the entry PRICE fails the shift test on
// back-adjusted continuous futures, whose price level is an arbitrary roll
// offset; K ATRs is the same scale-adaptive idea (the book's point on weekly
// and monthly charts) spelled as a difference.
//
// NOT AtrProfitTarget, which re-reads the LIVE ATR every bar and tests the
// dollar OpenPositionProfit (net of the entry side's costs, VERIFIED); this is
// the limit order Brooks places at entry -- the level is frozen on the fill bar
// and the test is on the closing price against a level, costs not included. Not
// StopLossTakeProfitATR, which also freezes the ATR at entry but carries a stop
// leg and tests dollars through a reward/risk multiple.
//
// BarsSinceEntry is 0 on the fill bar and 0 while flat (VERIFIED); the capture
// therefore also runs while flat with EntryPrice = 0.0, which is harmless
// behind the MarketPosition guard and is overwritten on the fill bar with the
// real entry price, exactly as StopLossTakeProfitATR captures its risk.
//
// The ATR is MultiWalk's WFSafe_AvgTrueRange in the ROLLING form of
// AtrProfitTarget: two accumulator statements and a re-seed on a length
// change. Every scratch value is a localVariables entry so the hooks survive a
// double placement. Deepest bar touched: atrLookback + 1.
if (atrLength != (int)atrLookback) {
    atrSum = 0.0;
    for (int i = 0; i < (int)atrLookback; ++i) {
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        atrSum += hi - lo;
    }
    atrLength = (int)atrLookback;
} else {
    const int out = (int)atrLookback;
    double hiIn = high[0] > close[1] ? high[0] : close[1];
    double loIn = low[0] < close[1] ? low[0] : close[1];
    double hiOut = high[out] > close[out + 1] ? high[out] : close[out + 1];
    double loOut = low[out] < close[out + 1] ? low[out] : close[out + 1];
    // TWO statements, not one. EasyLanguage writes
    //     Summation = Summation[1] + Price - Price[Length]
    // which evaluates left to right as (S + in) - out. Folding it to
    // S + (in - out) is a different rounding and lands on the other side of the
    // threshold at @OJ 2015-02-20: (S+in)-out gives 1722.4999999999977 and
    // fires, S+(in-out) gives 1722.5000000000066 and does not.
    atrSum += hiIn - loIn;
    atrSum -= hiOut - loOut;
}
atr = atrSum / (int)atrLookback;
if (ctx.BarsSinceEntry() == 0) {
    targetLong = ctx.EntryPrice() + scalpAtr * atr;
    targetShort = ctx.EntryPrice() - scalpAtr * atr;
}
